using System;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "TempestPollenOmenData", menuName = "Data/Battle/Omens System/Omen Data/Austra/TempestPollenOmenData")]
public class TempestPollenOmenData : OmenData
{
	[Header("Sent Pur Omen Data")]
	[SerializeField]
	private int amountToDivide = 2;

	public override void Initialize(OmenInstance omenInstance)
	{
		Action<int> tempestPollenOmenAction = delegate(int purifyAmount)
		{
			int actionValue = ReferenceSingleton<BattleHandler>.Instance.PlayerGameObject.GetComponent<PlayerEffects>().IsPlayerCriticalCheckCritical(Mathf.Max(Mathf.FloorToInt((float)purifyAmount / (float)amountToDivide), ActionValue), fierceSquall: false, sentPur: true);
			OmenLogic.ActivateOmen(null, actionValue, null, null);
		};
		ReferenceSingleton<AustraOmensHandler>.Instance.TempestPollenOmenAction = tempestPollenOmenAction;
	}

	public override void OmenRemoved()
	{
		ReferenceSingleton<AustraOmensHandler>.Instance.TempestPollenOmenAction = null;
	}

	public override string OmenConvertedDescription()
	{
		if (LanguagesIndexes.IsCurrentLanguageSimplifiedChinese())
		{
			return Smart.Format(GetOmenRawLocalizedDescription(), amountToDivide, base.localizationManager.GetLocalizedRoundedDown(), ActionValue) + "\n" + ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedThisPurifyCanTriggerCritical();
		}
		return Smart.Format(GetOmenRawLocalizedDescription(), BattleAction.GetActionDescription(1).RemoveLastIfDotOrComma(), amountToDivide, base.localizationManager.GetLocalizedRoundedDown(), ActionValue) + "\n" + ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedThisPurifyCanTriggerCritical();
	}
}
